begin;create extension if not exists pgtap with schema extensions;set local search_path=public,extensions;select plan(17);
insert into auth.users(id,email,raw_app_meta_data,raw_user_meta_data)values('1e000000-0000-4000-8000-000000000001','import-owner@example.test','{}','{}'),('1e000000-0000-4000-8000-000000000002','import-member@example.test','{}','{}'),('1e000000-0000-4000-8000-000000000003','import-outsider@example.test','{}','{}');insert into public.workspaces(id,name,owner_id)values('2e000000-0000-4000-8000-000000000001','Import Workspace','1e000000-0000-4000-8000-000000000001');insert into public.workspace_members(workspace_id,user_id,role)values('2e000000-0000-4000-8000-000000000001','1e000000-0000-4000-8000-000000000002','member');
insert into public.legacy_import_sessions(id,workspace_id,requested_by,source_sha256,schema_id,schema_revision,source_counts,control_totals,warnings,report_lines)values('3e000000-0000-4000-8000-000000000001','2e000000-0000-4000-8000-000000000001','1e000000-0000-4000-8000-000000000001',repeat('a',64),'evermont.finance.v1',11,'{"categories":{"source":1},"clients":{"source":1},"ledger":{"source":1}}','{"sourceMoney":"100.25","readyMoney":"100.25","duplicateMoney":"0.00"}','[]','["Preview ready."]');
insert into public.legacy_import_records(session_id,workspace_id,collection,legacy_id,fingerprint,payload,status)values
('3e000000-0000-4000-8000-000000000001','2e000000-0000-4000-8000-000000000001','categories','CAT-1',repeat('b',64),'{"name":"Advertising","kind":"expense","scheduleCLine":"Line 8"}','ready'),
('3e000000-0000-4000-8000-000000000001','2e000000-0000-4000-8000-000000000001','clients','CLI-1',repeat('c',64),'{"name":"Sample Client","email":"client@example.test"}','ready'),
('3e000000-0000-4000-8000-000000000001','2e000000-0000-4000-8000-000000000001','ledger','LED-1',repeat('d',64),'{"date":"2026-01-15","type":"expense","amount":"100.25","description":"Digital advertising","categoryId":"CAT-1"}','ready');
set local role authenticated;select throws_ok($$select public.commit_legacy_import('2e000000-0000-4000-8000-000000000001','1e000000-0000-4000-8000-000000000001','3e000000-0000-4000-8000-000000000001')$$,'42501',null,'authenticated clients cannot call the service import function');reset role;
create temporary table committed as select public.commit_legacy_import('2e000000-0000-4000-8000-000000000001','1e000000-0000-4000-8000-000000000001','3e000000-0000-4000-8000-000000000001')result;
select is((select result->>'status'from committed),'completed','valid staged import completes');select is((select result->>'imported'from committed),'3','all valid records import');select is((select status from public.legacy_import_sessions where id='3e000000-0000-4000-8000-000000000001'),'completed','session records completion');select is((select count(*)::integer from public.categories where workspace_id='2e000000-0000-4000-8000-000000000001'and name='Advertising'),1,'category imports');select is((select count(*)::integer from public.clients where workspace_id='2e000000-0000-4000-8000-000000000001'and display_name='Sample Client'),1,'client imports');select is((select amount::text from public.transactions where workspace_id='2e000000-0000-4000-8000-000000000001'),'100.25','ledger amount imports exactly');select is((select c.name from public.transactions t join public.categories c on c.id=t.category_id where t.workspace_id='2e000000-0000-4000-8000-000000000001'),'Advertising','legacy category relationship resolves');select is((select count(*)::integer from public.legacy_import_keys where workspace_id='2e000000-0000-4000-8000-000000000001'),3,'duplicate keys are retained');select is((select count(*)::integer from public.legacy_import_records where status='imported'),3,'staged rows retain imported status');select is((select count(*)::integer from public.audit_events where entity_type='legacy_backup'),1,'import writes an audit event');select is(public.commit_legacy_import('2e000000-0000-4000-8000-000000000001','1e000000-0000-4000-8000-000000000001','3e000000-0000-4000-8000-000000000001')->>'status','completed','commit retry is idempotent');
select throws_ok($$select public.commit_legacy_import('2e000000-0000-4000-8000-000000000001','1e000000-0000-4000-8000-000000000002','3e000000-0000-4000-8000-000000000001')$$,'P0001','Only workspace owners and administrators can import a legacy backup','members cannot commit imports');select throws_ok($$select public.commit_legacy_import('2e000000-0000-4000-8000-000000000001','1e000000-0000-4000-8000-000000000003','3e000000-0000-4000-8000-000000000001')$$,'P0001','Only workspace owners and administrators can import a legacy backup','outsiders cannot commit imports');
set local role authenticated;select set_config('request.jwt.claim.sub','1e000000-0000-4000-8000-000000000002',true);select is((select count(*)::integer from public.legacy_import_sessions),1,'workspace members can read import status');select set_config('request.jwt.claim.sub','1e000000-0000-4000-8000-000000000003',true);select is((select count(*)::integer from public.legacy_import_sessions),0,'outsiders cannot read import status');reset role;
select throws_ok($$insert into public.legacy_import_keys(workspace_id,collection,legacy_id,fingerprint)values('2e000000-0000-4000-8000-000000000001','ledger','LED-1',repeat('f',64))$$,'23505',null,'legacy identifiers cannot be imported twice');select * from finish();rollback;
